304			if err := rows.Scan(&e.seq, &e.account, &e.occurredAt, &e.prevHash, &e.hash); err != nil {
305				t.Fatalf("scan event: %v", err)
306			}
307			events = append(events, e)
308		}
309		if err := rows.Err(); err != nil {
310			t.Fatalf("iterate events: %v", err)
311		}
312		return events
313	}
